declare global {
    interface Int32ArrayConstructor {
        new (buffer: ArrayBuffer, byteOffset?: number, length?: number): Int32Array;
    }
    interface Float32ArrayConstructor {
        new (buffer: ArrayBuffer, byteOffset?: number, length?: number): Float32Array;
    }
}
